SELECT analytics_contract_facts.region, SUM(analytics_contract_facts.active_contract_value) AS active_contract_value FROM analytics_contract_facts WHERE analytics_contract_facts.year = 2026 AND analytics_contract_facts.month = 1 AND analytics_contract_facts.status = 'active' AND analytics_contract_facts.contract_risk = 'low' GROUP BY analytics_contract_facts.region ORDER BY active_contract_value DESC, analytics_contract_facts.region ASC LIMIT 10
